-- ==========================================================
-- ecommerce_seed.sql
-- Seed data for Spring Boot ecommerce demo + RabbitMQ
-- Safe to re-run: does not DROP/TRUNCATE tables or delete rows.
-- Existing users are preserved; demo users are inserted only if
-- their email does not already exist.
-- ==========================================================

USE ecommerce_db;
SET NAMES utf8mb4;

START TRANSACTION;

-- 1) Demo users
-- NOTE: passwords below are demo-only BCrypt-looking placeholders.
-- Replace them with valid hashes generated by your application's
-- PasswordEncoder if authentication/password login is tested.
INSERT INTO users (name, email, password, phone, address, created_at)
SELECT 'Nguyen Van An', 'an.demo@example.com',
       '$2a$10$N9qo8uLOickgneFDz8P3.O1xYf2z6Y7V9V6zjJ0u5Y5J5V5J5V5J5K',
       '0901000001', 'Quan 1, TP. Ho Chi Minh', NOW()
WHERE NOT EXISTS (SELECT 1 FROM users WHERE email = 'an.demo@example.com');

INSERT INTO users (name, email, password, phone, address, created_at)
SELECT 'Tran Thi Binh', 'binh.demo@example.com',
       '$2a$10$N9qo8uLOickgneFDz8P3.O1xYf2z6Y7V9V6zjJ0u5Y5J5V5J5V5J5K',
       '0901000002', 'Quan 3, TP. Ho Chi Minh', NOW()
WHERE NOT EXISTS (SELECT 1 FROM users WHERE email = 'binh.demo@example.com');

-- 2) Products (avoid duplicate demo products by name)
INSERT INTO products
    (name, description, price, category, image_url, stock_quantity, created_at, updated_at)
SELECT 'Laptop Dell Inspiron 15', 'Laptop phuc vu demo Spring Boot RabbitMQ',
       15000000, 'Laptop', 'https://example.com/laptop-dell.jpg', 20, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE name = 'Laptop Dell Inspiron 15');

INSERT INTO products
    (name, description, price, category, image_url, stock_quantity, created_at, updated_at)
SELECT 'Ban phim co Keychron K2', 'Ban phim co cho lap trinh',
       2200000, 'Phu kien', 'https://example.com/keychron-k2.jpg', 35, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE name = 'Ban phim co Keychron K2');

INSERT INTO products
    (name, description, price, category, image_url, stock_quantity, created_at, updated_at)
SELECT 'Chuot Logitech MX Master 3S', 'Chuot khong day cho cong viec',
       2500000, 'Phu kien', 'https://example.com/logitech-mx-master.jpg', 25, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE name = 'Chuot Logitech MX Master 3S');

INSERT INTO products
    (name, description, price, category, image_url, stock_quantity, created_at, updated_at)
SELECT 'Man hinh Dell 27 inch', 'Man hinh 27 inch phuc vu hoc tap va lam viec',
       6200000, 'Man hinh', 'https://example.com/dell-monitor.jpg', 12, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE name = 'Man hinh Dell 27 inch');

INSERT INTO products
    (name, description, price, category, image_url, stock_quantity, created_at, updated_at)
SELECT 'Tai nghe Sony WH-1000XM5', 'Tai nghe chong on',
       6900000, 'Am thanh', 'https://example.com/sony-headphones.jpg', 15, NOW(), NOW()
WHERE NOT EXISTS (SELECT 1 FROM products WHERE name = 'Tai nghe Sony WH-1000XM5');

-- 3) One cart for each demo user, only if they do not already have a cart
INSERT INTO carts (user_id, created_at, updated_at)
SELECT u.id, NOW(), NOW()
FROM users u
WHERE u.email IN ('an.demo@example.com', 'binh.demo@example.com')
  AND NOT EXISTS (SELECT 1 FROM carts c WHERE c.user_id = u.id);

-- 4) Cart items for demo carts, only if the same product is not already in that cart
INSERT INTO cart_items (cart_id, product_id, quantity)
SELECT c.id, p.id, 1
FROM carts c
JOIN users u ON u.id = c.user_id
JOIN products p ON p.name = 'Ban phim co Keychron K2'
WHERE u.email = 'an.demo@example.com'
  AND NOT EXISTS (
      SELECT 1 FROM cart_items ci
      WHERE ci.cart_id = c.id AND ci.product_id = p.id
  );

INSERT INTO cart_items (cart_id, product_id, quantity)
SELECT c.id, p.id, 1
FROM carts c
JOIN users u ON u.id = c.user_id
JOIN products p ON p.name = 'Chuot Logitech MX Master 3S'
WHERE u.email = 'an.demo@example.com'
  AND NOT EXISTS (
      SELECT 1 FROM cart_items ci
      WHERE ci.cart_id = c.id AND ci.product_id = p.id
  );

INSERT INTO cart_items (cart_id, product_id, quantity)
SELECT c.id, p.id, 1
FROM carts c
JOIN users u ON u.id = c.user_id
JOIN products p ON p.name = 'Tai nghe Sony WH-1000XM5'
WHERE u.email = 'binh.demo@example.com'
  AND NOT EXISTS (
      SELECT 1 FROM cart_items ci
      WHERE ci.cart_id = c.id AND ci.product_id = p.id
  );

-- 5) Demo orders are intentionally not inserted here.
-- Create orders through POST /api/orders so OrderService runs and
-- publishes order.created.queue messages to RabbitMQ.
-- This also ensures order/order_items follow the application's logic.

COMMIT;

-- Quick verification queries (read-only)
SELECT id, name, email FROM users
WHERE email IN ('an.demo@example.com', 'binh.demo@example.com');

SELECT id, name, price, stock_quantity FROM products
WHERE name IN (
  'Laptop Dell Inspiron 15',
  'Ban phim co Keychron K2',
  'Chuot Logitech MX Master 3S',
  'Man hinh Dell 27 inch',
  'Tai nghe Sony WH-1000XM5'
);

SELECT c.id AS cart_id, u.email, p.name AS product_name, ci.quantity
FROM carts c
JOIN users u ON u.id = c.user_id
JOIN cart_items ci ON ci.cart_id = c.id
JOIN products p ON p.id = ci.product_id
WHERE u.email IN ('an.demo@example.com', 'binh.demo@example.com')
ORDER BY c.id, p.name;
